/* Local, transactional saves. No player data leaves this browser. */
const DB='ashen-covenant-v2',VERSION=1,KEY='current';
let dbPromise;
export function openDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(new Error('此瀏覽器無法使用本機儲存。請改用一般模式。'));const r=indexedDB.open(DB,VERSION);r.onupgradeneeded=()=>{const d=r.result;for(const n of ['save','archives'])if(!d.objectStoreNames.contains(n))d.createObjectStore(n)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('請關閉另一個舊遊戲分頁，再重新開啟。'))});return dbPromise}
export async function readSave(){const db=await openDB();return new Promise((resolve,reject)=>{const t=db.transaction('save','readonly'),r=t.objectStore('save').get(KEY);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
export async function writeSave(state,expectedRevision,resolvedAt,options={}){if(!Number.isSafeInteger(expectedRevision)||expectedRevision<0||!Number.isFinite(resolvedAt)||resolvedAt<0)throw new Error('儲存版本或時間無效。');const db=await openDB();return new Promise((resolve,reject)=>{let result,failed=false;const tx=db.transaction(['save','archives'],'readwrite'),store=tx.objectStore('save'),r=store.get(KEY);function fail(e){failed=true;reject(e);try{tx.abort()}catch{}}r.onsuccess=()=>{const old=r.result;if((old?.revision||0)!==expectedRevision)return fail(new Error('另一個分頁已更新進度。請重新載入，避免覆寫。'));try{if(options.archive&&old)tx.objectStore('archives').put(old,'before-'+String(old.revision));result={schema:2,revision:expectedRevision+1,resolvedAt,state:structuredClone(state)};store.put(result,KEY)}catch(e){fail(e)}};r.onerror=()=>fail(r.error);tx.oncomplete=()=>resolve(result);tx.onerror=()=>{if(!failed)reject(tx.error||new Error('儲存失敗'))};tx.onabort=()=>{if(!failed)reject(tx.error||new Error('儲存未完成'))}})}
export async function preserveLegacy(raw){if(typeof raw!=='string')return;const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('archives','readwrite'),s=tx.objectStore('archives'),r=s.get('v1-original');r.onsuccess=()=>{if(!r.result)s.put({format:'v1-raw',raw},'v1-original')};tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
export async function readLegacy(){let raw=null;try{raw=localStorage.getItem('ashen-covenant-v1')}catch{}if(raw){await preserveLegacy(raw);return raw}const db=await openDB();return new Promise((resolve,reject)=>{let t=db.transaction('archives','readonly'),r=t.objectStore('archives').get('v1-original');r.onsuccess=()=>resolve(r.result?.raw||null);r.onerror=()=>reject(r.error)})}
export async function acquireSession(){if(navigator.locks?.request){let release,resolveReady;const ready=new Promise(r=>resolveReady=r);navigator.locks.request('ashen-covenant-play',{ifAvailable:true},async lock=>{if(!lock){resolveReady(false);return}const hold=new Promise(r=>release=r);resolveReady(true);await hold}).catch(()=>resolveReady(false));const owned=await ready;return{owned,release:()=>release?.()}}// IndexedDB CAS still protects unsupported browsers against stale overwrites.
return{owned:true,release(){},warning:'此瀏覽器以存檔版本檢查防止多分頁覆寫。'}}
export async function listArchives(){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('archives','readonly'),store=tx.objectStore('archives'),r=store.getAll();r.onsuccess=()=>resolve(r.result.filter(v=>v?.schema===2&&v.state).sort((a,b)=>b.revision-a.revision));r.onerror=()=>reject(r.error)})}
